def knapsack(w, v, cap):
    n = len(w)
    dp = [[0]*(cap+1) for _ in range(n+1)]
    for i in range(1, n+1):
        for c in range(cap+1):
            if w[i-1] <= c:
                dp[i][c] = max(v[i-1]+dp[i-1][c-w[i-1]], dp[i-1][c])
            else:
                dp[i][c] = dp[i-1][c]
    return dp[n][cap]

